INSERT INTO `items` VALUES (1,'UGREEN Wireless Mouse','Tech and Gadgets','Ultra-fast wireless performance with Bluetooth 5.4 & 2.4Ghz Experience seamless connectivity using Bluetooth 5.4 and 2.4Ghz wireless technology, ensuring low latency and stable performance across devices like MacBook, tablet, and PC.\r\nHigh-precision 5000 DPI for smooth scrolling Equipped with a 5000 DPI sensor, this mouse delivers accurate tracking and responsive movement, ideal for fast-paced tasks and precise cursor control on any surface.\r\n6-button design with ergonomic comfort Featuring 6 programmable buttons and an ergonomic design, it offers enhanced usability and reduces hand fatigue during extended use on laptops or desktops.',23.00,5,'/images/1782887740677-screenshot-2026-07-01_09-32-06.png'),(2,'UGREEN Wireless Headphones','Tech and Gadgets','Advanced Active Noise Cancellation Experience immersive sound with 48dB ANC technology, effectively blocking out external noise for a distraction-free listening environment, perfect for travel or focused work.\r\nExtended 120-Hour Battery Life Enjoy up to 120 hours of playback time on a single charge, making the UGREEN Studio Pro ideal for long trips or extended daily use without frequent recharging.\r\nBluetooth 6.0 & Hi-Res LDAC Support Powered by Bluetooth 6.0 and supporting LDAC codec, this headset delivers high-resolution audio with minimal latency and superior sound clarity.',47.00,50,'/images/1782888010361-screenshot-2026-07-01_09-37-30.png'),(3,'UGREEN Uno USB C HUB','Tech and Gadgets','6-in-1 versatile USB-C hub with 10Gbps speed The UGREEN Uno USB-C HUB delivers fast data transfer up to 10Gbps via 2x USB-A and 2x USB-C ports, ensuring efficient file sharing and device connectivity for all your needs.\r\nSupports 4K60Hz HDMI output with HDR Equipped with HDMI 2.0, this adapter supports 3840×2160@60Hz resolution and HDR, providing crystal-clear video output for presentations, movies, and gaming on external displays.\r\nPowerful 100W PD charging via USB-C With a USB-C PD3.0 100W charging port, it can power and charge your laptop or device while connected, ensuring uninterrupted performance during work or play.',23.00,10,'/images/1782888097190-screenshot-2026-07-01_09-40-49.png'),(5,'HK11 SmartWatch','Tech and Gadgets','Latest 2025 HK11 Pro Max+ Smartwatch Experience the future with the 2025 New HK11 Pro Max Plus, featuring advanced AMOLED display and ChatGPT 2.0 AI Robot integration for smarter interactions and real-time assistance.\r\nPowerful AI & Smart Features Equipped with AI Robot and Dynamic Island functionality, this smartwatch delivers intelligent responses, seamless app control, and enhanced user experience across daily tasks.\r\nComprehensive Health & Fitness Tracking Track heart rate, sleep, steps, calories, distance, and more with precision. The fitness tracker supports 24/7 monitoring and includes sleep tracker and passometer for active lifestyles.',136.00,49,'/images/1782892277017-screenshot-2026-07-01_10-50-33.png'),(6,'UGREEN 100W Charger','Tech and Gadgets','100W GaN Desktop Charger with 6-in-1 Multi-Device Support The UGREEN 100W GaN Charger delivers powerful, fast charging for up to 6 devices simultaneously, supporting iPhone 17, 16, 15 Pro Max, MacBook Air, iPad, Samsung, Xiaomi, and more with its versatile output interfaces.\r\nUltra-Fast Charging with Advanced Protocols Equipped with USB PD, Qualcomm Quick Charge, Huawei FCP, Samsung Adaptive Fast Charge, and Quick Charge compatibility, this charger ensures rapid and safe charging across a wide range of devices.\r\nIntelligent Charge Technology for Safety & Efficiency Featuring Intelligent Charge and 100W Max Output Power, the charger automatically detects device requirements to deliver optimal power while preventing overheating and overcharging.',31.00,5,'/images/1782892427317-screenshot-2026-07-01_10-52-45.png'),(7,'Bluetooth AUX Jack','Tech and Gadgets','Wireless Bluetooth-Compatible Audio Receiver This Bluetooth-Compatible Adapter enables wireless audio transmission from devices like phones, iPads, and Android tablets to any speaker or audio system with a 3.5mm jack.\r\nUniversal 3.5mm AUX Jack Support Equipped with a standard 3.5mm Jack, this adapter connects seamlessly to headphones, speakers, and car audio systems for instant wireless music playback.\r\nUSB-Powered for Continuous Use Powered via USB, this compact receiver ensures stable performance without draining device batteries, making it ideal for long listening sessions.',5.00,100,'/images/1782892526616-screenshot-2026-07-01_10-54-44.png'),(8,'Mini Metal USB Flash Drive','Tech and Gadgets','Read Speed: 10MB -18MB/second\r\n● Write Speed: 5MB -8MB/second\r\n● USB 2.0 interface with higher speed and higher stability\r\n● Portable, lightweight, high-quality metal protects the connector\r\n●Environment Temperature:  -40°C - +70°C\r\n●Storage Temperature: -50°C - +80°C\r\n●USB Service Voltage: 4.5V-5.5V\r\n●Storage Lifetime: More than 5 years\r\n●Use A-class chip, can be erased repeatedly for 100,0000 times\r\n●Operating System: Win98/ME/2000/XP/ Vista/win7 /win8, Mac OS 9.X/Linux2.4 or above\r\n●USB connection:support Hot plug & Play.\r\n●Easy to read and read in high speed ,No need drive/power supply only plug in.',10.00,100,'/images/1782892675192-screenshot-2026-07-01_10-56-38.png'),(9,'Wireless Neckband Earphone','Tech and Gadgets','Wireless Bluetooth Earphones Neckband Headphones Gaming Stereo Sports Headset Halter Waterproof Magnetic Earbud with LED Display',3.00,45,'/images/1782892834030-screenshot-2026-07-01_10-58-35.png'),(10,'Waterproof Earphone','Tech and Gadgets','20-Hour Playtime for Extended Use Enjoy up to 20 hours of playtime with the luxuglow TWS earbuds, perfect for long workouts, travel, or daily use without frequent recharging.\r\nIPX7 Waterproof & Swimming Ready Designed for active lifestyles, these earbuds feature IPX7 waterproof rating, making them ideal for swimming, sweating, or use in rainy conditions without damage.\r\nAdvanced Bluetooth 5.1 & Stable Connection Equipped with Bluetooth 5.1, the earbuds deliver a stable, low-latency connection with a maximum wireless range of less than 10 meters for seamless audio streaming.',20.00,50,'/images/1782893057588-screenshot-2026-07-01_11-03-37.png'),(11,'Smart Stainless Steel Ring','Tech and Gadgets','Smart mood-changing color ring for couples This multifunctional stainless steel ring changes color based on body temperature, making it a unique and interactive accessory for couples who love innovative fashion statements.\r\nWaterproof and durable stainless steel design Crafted from stainless steel with a waterproof finish, this ring ensures long-lasting wear and resistance to daily elements, ideal for active lifestyles and frequent use.\r\nAvailable in multiple stylish colors Choose from Black, Blue, Gold, Rose, and Silver metal colors to match your personal style or coordinate with your partner for a perfect couple’s look.',40.00,55,'/images/1782893152976-screenshot-2026-07-01_11-05-10.png'),(12,'Wireless Audio Adaptor','Tech and Gadgets','B6 Bluetooth-Compatible Wireless Audio Adapter This Music Wireless Adapter supports B6 Bluetooth technology, enabling seamless wireless audio transmission between devices like PC, TV, and car systems with minimal latency and strong connectivity.\r\nUniversal 3.5mm AUX Compatibility Equipped with a 3.5mm AUX interface, this adapter connects effortlessly to any device with a standard audio jack, making it ideal for headphones, speakers, and older audio systems without Bluetooth.\r\nPlug-and-Play Wireless Solution The Wireless Audio Adapter offers a simple setupjust plug in the 3.5mm jack and pair via Bluetooth. No complex configuration needed, perfect for quick use at home, in the car, or during travel.',10.00,30,'/images/1782893240868-screenshot-2026-07-01_11-06-44.png'),(13,'300Mbps Wifi Repeater','Tech and Gadgets','High-Speed WiFi Repeater :Experience seamless internet connectivity with this WiFi repeater that offers a maximum LAN data rate of 300Mbps. Ideal for large homes or offices with weak internet signal.\r\n\r\n• Long Range Signal Booster :This wireless WiFi repeater ensures comprehensive coverage by enhancing the signal strength over a long range, eliminating dead spots in your home or office.\r\n\r\n• Easy Installation :With its user-friendly design, this WiFi extender can be easily set up without the need for professional assistance. Simply plug it in and enjoy better WiFi signal.\r\n\r\n• Durable Construction :This WiFi repeater is built with high-quality materials, guaranteeing durability and longevity for long-term use.\r\n\r\n• Compatible with Brands :This versatile WiFi extender is compatible with brands, making it a practical choice for those who prefer to mix and match their electronic devices.\r\n\r\n300M signal enhancer: The signal enhancer provides a speed of up to 300Mbps, allowing you to enjoy a fast and stable internet connection.',50.00,10,'/images/1782893338483-screenshot-2026-07-01_11-08-03.png'),(14,'Men\'s Casual Shirt and Shorts','Fashion','Stylish two-piece summer set for men This Men\'s Casual Two-piece Jacquard Shirt and Shorts set offers a modern, relaxed look perfect for beach outings and summer vacations. Designed with a solid color pattern in classic black and white, it ensures timeless style.\r\nComfortable polyester fabric Crafted from POLYESTER material with STANDARD thickness, this set provides lightweight comfort and breathability. Ideal for warm weather, it ensures all-day ease during beach trips or casual wear.\r\nPerfect fit with multiple sizes Available in sizes S, M, L, XL, XXL, this set fits a wide range of body types. The drawstring pant closure and zipper shirt closure offer adjustable comfort and a secure fit.',12.00,30,'/images/1782893532765-screenshot-2026-07-01_11-11-25.png'),(15,'Men\'s Summer T-shirt and Short','Fashion','Perfect for summer casual wear This men\'s summer sports short sleeve set is ideal for daily use during warm seasons, offering comfort and style with its lightweight design and breathable fabric.\r\nQuick-dry and breathable fabric Made from POLYESTER with a knit weave, this set ensures quick-drying performance and excellent breathability for active summer days.\r\nStylish two-piece coordinated set Featuring a print pattern and matching O-neck T-shirt and shorts, this T-Shirts Co-ords set delivers a modern, coordinated look for casual outings.',20.00,10,'/images/1782893638752-screenshot-2026-07-01_11-13-02.png'),(16,'New Style Men\'s Pants','Fashion','2025 Summer New Style Lightweight Breathable Smooth and Loose Straight Sweatpants Draped and Elastic Home Men\'s Casual Pants',27.00,44,'/images/1782893777734-screenshot-2026-07-01_11-14-33.png'),(17,'Men Black Sweat Pants','Fashion','Y2K Happy Print Joggers Men Black Casual Drawstring Elastic Waist Streetwear Sweatpants\r\n',44.00,20,'/images/1782894304232-screenshot-2026-07-01_11-16-54.png'),(18,'Women Long Sleeve Dress','Fashion','Elegant Wine Red Slim Formal Dress V Neck Long Sleeve Crystal Beaded Ruched Waist Flowy Ankle Length Banquet Party Evening Dress',80.00,3,'/images/1782893947361-screenshot-2026-07-01_11-18-21.png'),(20,'Women\'s Sleeveless Dress ','Fashion','Elegant tea-length evening gown for formal events This Tea-Length dress features a Modern Style silhouette, perfect for proms, galas, or formal parties. Its straight silhouette and O-Neck design offer a timeless, sophisticated look suitable for all ages.\r\nStunning beading and pearl decoration Adorned with intricate Beading and Pearls, this dress adds a touch of luxury. The mono pattern and delicate Tatting craftsmanship enhance its elegance, making it stand out at any formal evening occasion.\r\nComfortable and supportive fit with built-in bra Designed with a Built-in Bra, this dress ensures a secure and comfortable fit without needing additional support. The Natural Waistline and Short Sleeves  provide a balanced, flattering look for all body types.',118.00,23,'/images/1782894104081-screenshot-2026-07-01_11-20-59.png'),(21,'Luxury Women Evening Dress','Fashion','Luxury floor-length evening dress for formal events This floor-length prom dress features an elegant A-line silhouette and is perfect for formal evening occasions such as galas, weddings, or red carpet events. Its sophisticated design ensures you stand out with timeless grace.\r\nExquisite beading and tatting craftsmanship Adorned with intricate beading decoration and delicate tatting weaving, this gown showcases high-end fashion details. The craftsmanship enhances the dress’s luxury appeal, making it a standout choice for special nights.\r\nCustomizable fit with built-in bra support Designed with a built-in bra and available in custom-made sizes, this dress ensures a comfortable, secure fit for all body types. The natural waistline enhances the figure while maintaining elegance.',123.00,4,'/images/1782894208221-screenshot-2026-07-01_11-22-46.png'),(22,'Women V-Neck Dress','Fashion','Elegant V-Neck A-Line Silhouette This evening dress features a flattering V-Neck and A-Line silhouette, designed to enhance the natural waistline and create a graceful, timeless look perfect for formal events.\r\nChiffon Fabric with Pleated Detail Crafted from lightweight chiffon fabric with a pleated decoration, this dress offers a soft drape and subtle texture, adding elegance and movement to every step.\r\nFull-Length Ankle-Length Design With a full-length ankle-length style, this formal gown ensures a sophisticated appearance, ideal for proms, galas, and other formal evening occasions.',69.00,33,'/images/1782894438733-screenshot-2026-07-01_11-26-33.png'),(23,'Cement 50kg Dumbbell','Sports and Outdoors','Durable Cement Material:Crafted from robust cement, these dumbbells withstand rigorous gym use and maintain their shape.\r\nVersatile Combinations:One piece for multiple purposes, these dumbbells offer 3 combinations for diverse workout routines.\r\nWeight Training Dumbbells And Bar Kit 50 Kg|Cement Dumbbells|Adjustable Weight Range:Customize your workout with 10-50Kg adjustable dumbbells, perfect for progressive strength training.',13.00,5,'/images/1782894531435-screenshot-2026-07-01_11-28-08.png'),(24,'Electric Bicycle','Sports and Outdoors','High-performance road bike for competitive cycling Designed for serious riders, this 24-speed electronic gear shift road bike delivers precise shifting and optimal power transfer on long-distance rides and triathlons.\r\nLightweight carbon fiber construction Built with carbon fibre frame and fork, this bike ensures superior strength-to-weight ratio, enhancing speed and ride efficiency on demanding terrain.\r\nAdvanced double disc braking system Equipped with a double disc brake system, this bike offers reliable stopping power in all weather conditions, ensuring safety and control at high speeds.',700.00,23,'/images/1782894624439-screenshot-2026-07-01_11-29-33.png'),(25,'1000W Electric Bike','Sports and Outdoors','Advanced Braking System:Features front disk & rear drum braking for a reliable and responsive stopping power in varied conditions.\r\nComfortable Ride:The electric bike\'s hydraulic front fork and 14*2.75 vacuum tire provide a smooth and comfortable ride.\r\nElectric Bike Aliexpress|Aliexpress Electric Bike|High-Power Motor:Equipped with a robust 1000W rear hub motor, this electric bike ensures a swift 30-50Km/h max speed.',721.00,6,'/images/1782894754589-screenshot-2026-07-01_11-31-56.png'),(26,'Ice Hockey Helmet','Sports and Outdoors','Integrated Ear Protection:Features a fast energy absorbing buffer for integrated ear protection, enhancing safety during play.\r\nVersatile Sports Helmet:Ideal for rugby, ice hockey, and land ice hockey, this helmet is a versatile safety top for various sports.\r\nDual-Density Foam Lining:The dual-density foam lining provides superior comfort and cushioning, reducing impact shocks.\r\n',43.00,2,'/images/1782894888183-screenshot-2026-07-01_11-34-23.png'),(27,'Baseball Bat','Sports and Outdoors','Name: Baseball Bat\r\n\r\nColor: Wood Material: Hardwood Size: 74cm, 84cm (error +-2cm)\r\n\r\nUsed people,men,women,kids,adult Package includes: 1*Baseball Bat\r\n\r\nFeatures\r\n\r\n1. High Quality Solid Wood\r\n\r\n2. Durable\r\n\r\n3. Suitable for all ages\r\n\r\n4. Multi-purpose\r\n\r\n\r\nSuggestion \r\n\r\n54cm suit for teenagers or kids\r\n\r\n64cm suit for people under 173cm\r\n\r\n74cm suit for people under 180cm\r\n\r\n84cm suit for people under 185cm',13.00,500,'/images/1782894988899-screenshot-2026-07-01_11-35-45.png'),(28,'PU Leather Ball','Sports and Outdoors','Stylish: This PU leather football adopts machine stitched and has a beautiful and eye-catching pattern, making the ball more outstanding.\r\nSuitable occasions: This waterproof leather soccer ball is a good fit for a match, competition, game, training, practise, exercise, and so on.\r\nPortable: This PU leather soccer ball is a size 5 ball and the diameter is about 21.5cm, so it is convenient to carry and is easy to store when you don’t use it.\r\nFine workmanship: This PU leather football is well crafted and has a smooth and fine surface that makes the ball comfortable to use.\r\nLong lifespan: This soccer ball is made of strong and sturdy PU leather and is durable and not easy to be worn out and it is anti-pressure.\r\nSpecification:\r\nMaterial: PU.\r\nColor: Blue, white, red, yellow.',23.00,44,'/images/1782895057464-screenshot-2026-07-01_11-37-06.png'),(29,'Electric Pedal','Sports and Outdoors','Electric pedal for comprehensive rehabilitation This stepper rehabilitation equipment is designed for both upper and lower limb exercises, supporting elderly users in improving mobility and muscle strength through targeted training sessions.\r\nCompact and lightweight design With a package size of 60 x 30 x 10 cm and a weight of 7.000 kg, this device is easy to store and transport, making it ideal for home use in limited spaces.\r\nStable black base for safe operation Featuring a durable black bottom base, the stepper ensures stability during use, providing a secure foundation for safe and effective leg and hand exercises.',200.00,3,'/images/1782895168142-screenshot-2026-07-01_11-38-49.png'),(30,'Foot Bare Ankle Exerciser','Sports and Outdoors','Foot Bare Ankle Exerciser Inability to Move Upturn Foot Sagging Achilles Tendon Stretching After Ankle Fracture',178.00,43,'/images/1782895252229-screenshot-2026-07-01_11-40-09.png'),(31,'Juice Blender','Home and Kitchen','Double cylinder parameter\r\nModel:LYJ18-2\r\nRated Voltage: 220V/50Hz\r\nCooling Rated Power: 400W\r\nHeating Rated Power: 1150W\r\nGross weight：30KG\r\nCapacity: 18L*2\r\nCooling Temperature: 7-12℃\r\nHeating Temperature: 52-58℃\r\nSize: 460*437*670mm/18.2*17.3*26.4in',1714.00,2,'/images/1782895425816-screenshot-2026-07-01_11-43-02.png'),(32,'5L Electric Beer Dispenser','Home and Kitchen','220V Automatic 5L Electric Beer Dispensers，LED Temperature Display Screen,Temperature Adjustable Can Hold Carbonated Beverages\r\n2 sold',476.00,30,'/images/1782896296032-screenshot-2026-07-01_11-57-39.png'),(33,'Automatic Fruit Juicer','Home and Kitchen','High-capacity fully automatic juicer This 1000C-1 juicer features a 1501-2000ml capacity, ideal for commercial use. It efficiently handles large volumes of citrus fruits with minimal effort, perfect for busy cafes or restaurants.\r\nStainless steel construction for durability Built with stainless steel housing, cup body, and blade, this juicer resists rust and corrosion. The robust build ensures long-term performance and hygiene in high-use environments.\r\nAutomatic pulp ejection system Equipped with automatic pulp ejection, the juicer clears residue instantly after use. This feature reduces cleaning time and maintains consistent juicing efficiency across batches.',516.00,34,'/images/1782896348972-screenshot-2026-07-01_11-58-42.png'),(34,'Smart Android TV','Home and Kitchen','32 Inch Smart Android TV Full HD 1080p LED Flat Screen Television, WiFi HDMI USB Google Play Netflix, Budget Home & Hotel TV',192.00,31,'/images/1782896582104-screenshot-2026-07-01_12-00-00.png'),(35,'Portable Touch Screen Display','Home and Kitchen','Portable Smart Touch Screen TV Display 8-core Android 13 Portable Tv for Home Lcd Mobile Touch Screen Monitor 8g+128g',624.00,20,'/images/1782896676450-screenshot-2026-07-01_12-03-53.png'),(36,'Oil presser','Home and Kitchen','Oil press home small automatic multi-functional commercial oil residue new fried oil intelligent oil press machine',134.00,45,'/images/1782896735993-screenshot-2026-07-01_12-05-07.png'),(37,'Hot Chocolate Machine','Home and Kitchen','Commercial Hot Chocolate Machine Drinking Hot Chocolate Dispenser Milk Tea Soy Bean Coffee Wine Dispenser Kitchen Appliance',304.00,2,'/images/1782896798930-screenshot-2026-07-01_12-06-12.png'),(38,'Mini Popcorn Maker','Home and Kitchen','220V/110V Kids Favorite Mini Popcorn Maker Home Appliance Electric Automatic Popcorn Machine',17.00,4,'/images/1782896850936-screenshot-2026-07-01_12-07-02.png');
